    {
      "section": "5.4.4.1",
      "label": "[REQ-1-OAD-9832]",
      "text": "The Semester Scheduling Subsystem shall provide scheduling support for synoptic or cadence observations during Pre-planned Queue periods.",
      "id": "REQ-1-OAD-9832"
    },
    {
      "section": "5.4.4.1",
      "label": null,
      "text": "Cadence and synoptic observations must be supported in the semester schedule.",
